module drink_partition_counter #(\n    parameter MAX_N = 8,\n    parameter MAX_PAIRS = 8,\n    parameter MOD = 1000000007\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [3:0] P,\n    input wire [8*MAX_PAIRS-1:0] pairs_packed,\n    output reg [15:0] result,\n    output reg done\n);\n\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] DONE = 2'd1;\n    reg [1:0] state;\n    reg [15:0] result_comb;\n    reg [7:0] pairs [0:MAX_PAIRS-1];\n    reg [3:0] max_bad [1:MAX_N];\n    reg [3:0] left_limit [1:MAX_N];\n    reg [15:0] dp [0:MAX_N];\n    integer i, j, k;\n\n    always @(*) begin\n        for (k = 0; k < MAX_PAIRS; k = k + 1) begin\n            pairs[k] = pairs_packed[8*k +: 8];\n        end\n\n        for (i = 1; i <= MAX_N; i = i + 1) begin\n            max_bad[i] = 4'd0;\n        end\n\n        for (k = 0; k < MAX_PAIRS; k = k + 1) begin\n            if (k < P) begin\n                reg [3:0] a = pairs[k][3:0];\n                reg [3:0] b = pairs[k][7:4];\n                if (a != 4'd0 && b != 4'd0 && a <= N && b <= N && a != b) begin\n                    if (a < b) begin\n                        if (a > max_bad[b]) max_bad[b] = a;\n                    end else begin\n                        if (b > max_bad[a]) max_bad[a] = b;\n                    end\n                end\n            end\n        end\n\n        for (i = 1; i <= MAX_N; i = i + 1) begin\n            if (i == 4'd1) begin\n                left_limit[i] = max_bad[i] + 4'd1;\n            end else begin\n                left_limit[i] = max_bad[i] + 4'd1;\n                if (left_limit[i-1] > left_limit[i]) begin\n                    left_limit[i] = left_limit[i-1];\n                end\n            end\n        end\n\n        dp[0] = 16'd1;\n        for (i = 1; i <= N; i = i + 1) begin\n            reg [15:0] sum = 16'd0;\n            for (j = left_limit[i] - 4'd1; j <= (i-1); j = j + 1) begin\n                if (j >= 0) sum = sum + dp[j];\n            end\n            dp[i] = sum;\n        end\n\n        result_comb = dp[N];\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        result <= result_comb;\n                        state <= DONE;\n                    end\n                end\n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule